class GFG {
  static boolean doesContainB ( int a , int b , int c ) {
    if ( a == b ) {
      return true ;
    }
    if ( ( b - a ) * c > 0 && ( b - a ) % c == 0 ) {
      return true ;
    }
    return false ;
  }
  public static void main ( String [ ] args ) {
    int a = 1 , b = 7 , c = 3 ;
    if ( doesContainB ( a , b , c ) ) {
      System . out . println ( "Yes" ) ;
    }
    else {
      System . out . println ( "No" ) ;
    }
  }
}

