    int len = ( int ) Math . ceil ( Math . log10 ( n ) ) ;
    for ( int i = 0 ;
    i < len ;
    i ++ ) {
      if ( n % 2 != 0 ) {
        return n ;
      }
      else {
        n = ( n / 10 ) + ( n % 10 ) * ( int ) Math . pow ( 10 , len - i - 1 ) ;
        continue ;
      }
    }
    return - 1 ;
  }
