class GFG {
  static final int MOD = 1000000007 ;
  static int rangeSum ( int l , int r ) {
    int a = 1 , b = 9 , res = 0 ;
    for ( int i = 1 ;
    i <= 10 ;
    i ++ ) {
      int L = Math . max ( l , a ) ;
      int R = Math . min ( r , b ) ;
      if ( L <= R ) {
        int sum = ( L + R ) * ( R - L + 1 ) / 2 ;
        res += ( i * i ) * ( sum % MOD ) ;
        res %= MOD ;
      }
      a = a * 10 ;
      b = b * 10 + 9 ;
    }
    return res ;
  }
  public static void main ( String args [ ] ) {
    int l = 98 , r = 102 ;
    System . out . print ( rangeSum ( l , r ) ) ;
  }
}

