  int i = 0 , mod = 1 ;
  while ( i < x ) {
    mod *= 10 ;
    i ++ ;
  }
  int last = n % mod ;
  long long len = digitsCount ( n ) ;
  while ( len != x ) {
    n /= 10 ;
    len -- ;
  }
