        } else if(sa ==(dpketa[pp-1]+2)) {
            count += niku[pp-1] + 1;
            break;
        } else if(sa > 1) {
            sa -= 1;
        } else if(sa == 1) {
            break;
        }
    } else if(pp == 1){
        switch(sa) {
            case 1: break;
            case 5:
            case 4: count++;
            case 3: count++;
            case 2: count++;
        }
        break;
    } else if(pp == 0 && sa == 1) {
        count++;
        break;
    } else break;
    }
    cout << count << endl;
    return 0; 
