            var I = int.Parse(n[1]);
            var dp = new int[I + 1, J + 1];

            for (int i = 0; i <= I; i++)
            {
                for (int j = 0; j <= J; j++)
                {
                    if (i == 0 || j == 0)
                    {
                        dp[i, j] = 0;
                    }
                    else
                    {
                        dp[i, j] = int.MaxValue;
                    }
                    if (i == 1)
                    {
                        dp[i, j] = j;
                    }
                }
            }

            for (int i = 1; i < I; i++)
            {
                for (int j = 0; j < J + 1; j++)
                {
                    if (j - int.Parse(c[i]) >= 0)
                    {
                        dp[i + 1, j]
                            = Math.Min(
                                dp[i, j],
                                dp[i + 1, j - int.Parse(c[i])] + 1);
                    }
                    else
                    {
                        dp[i + 1, j] = dp[i, j];
                    }
                }
            }
            var min = int.MaxValue;
            for (int i = 1; i < I+1; i++)
            {
