		for(int i=0;nn>0;i++){
			nb[i] = nn & 1;
			nn >>= 1;
		}

		int maxlen = 512;
		int ans[] = new int[maxlen];
		for(int i = 0;i<32;i+=2){
			if(n>=0){
				if(nb[i] == 1 && nb[i+1] == 0)
					ans[i]++;
				else if(nb[i] == 0 && nb[i+1] == 1){
					ans[i+1]++;
					ans[i+2]++;
				}
				else if(nb[i] == 1 && nb[i+1] == 1){
					ans[i]++;
					ans[i+1]++;
					ans[i+2]++;
				}
			}
			else{
				if(nb[i] == 1 && nb[i+1] == 0){
					ans[i]++;
					ans[i+1]++;
				}
				else if(nb[i] == 0 && nb[i+1] == 1){
					ans[i+1]++;
				}
				else if(nb[i] == 1 && nb[i+1] == 1){
					ans[i]++;
					ans[i+2]++;
					ans[i+3]++;
				}
			}
		}

		for(int i=0;i<maxlen-3;i++){
			int d = Math.min(ans[i] / 2, ans[i+1]);
